# One line per case: the function's result as JSON, or "raises <Error>".
import importlib, json, sys

module, name = sys.argv[1], sys.argv[2]
fn = getattr(importlib.import_module(module), name)
for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    try:
        args = json.loads(line)
        out = fn(*args) if isinstance(args, list) else fn(args)
        print(json.dumps(out, sort_keys=True, default=repr))
    except Exception as e:
        print("raises " + type(e).__name__)
